#!/usr/bin/env bash
# Logo/company uploads — sunucuda:
#   cd /var/www/tatil-villa && bash scripts/deploy/bootstrap-company-uploads.sh
set -euo pipefail
APP_DIR="${APP_DIR:-/var/www/tatil-villa}"
DEST="$APP_DIR/public/uploads"
mkdir -p "$DEST"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
base64 -d <<'B64' > "$TMP/company.tar"

B64
tar -xf "$TMP/company.tar" -C "$DEST"
chmod -R a+rX "$DEST/company"
echo "OK: $(find "$DEST/company" -type f | wc -l) dosya -> $DEST/company"
curl -sI "http://127.0.0.1:3000/uploads/company/logo-1783080885848.svg" | head -3 || true
